    vowels = ['a', 'e', 'i', 'o', 'u']
    reverse_vowels_list = []
    for i in range(len(string)):
        if string[i] not in vowels:
            reverse_vowels_list.append(string[i])
    return ''.join(reverse_vowels_list)


